CREATE FUNCTION public.prelaunch_history_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d date; BEGIN IF coalesce(trim(NEW.description),'')='' THEN RAISE EXCEPTION 'Describe what was done'; END IF; IF NEW.evidence_url IS NOT NULL AND NEW.evidence_url !~ '^https://' THEN RAISE EXCEPTION 'Evidence must be an HTTPS link'; END IF; SELECT coalesce(launch_date,day0_date,contract_start) INTO d FROM client_launches WHERE client_id=NEW.client_id AND status IN('active','live','on_hold','offboarding') ORDER BY created_at DESC LIMIT 1; IF d IS NOT NULL AND NEW.work_date>=d THEN RAISE EXCEPTION 'Pre-launch history must be dated before the launch date'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.prelaunch_history_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER a_prelaunch_history_guard BEFORE INSERT ON public.prelaunch_work_history FOR EACH ROW EXECUTE FUNCTION public.prelaunch_history_guard();
DO $ddl$ DECLARE d text; BEGIN SELECT pg_get_functiondef('public.gate_a_lock_guard()'::regprocedure) INTO d; d:=replace(d,'NEW.status NOT IN(''not_started'',''done'',''not_applicable'')','(NEW.status NOT IN(''not_started'',''not_applicable'') AND NOT (NEW.status=''done'' AND NEW.carried_from_task_id IS NOT NULL))'); EXECUTE d; END $ddl$;